    def test_encrypted_credentials(self) -> None:
        """Use case: Configure carrier secrets. Expected result: only encrypted data persists."""
        # 1. Persist a configured account.
        self.prepare_voip()
        # 2. Verify server-only round trip and absence of plaintext.
        self.connection.refresh_from_db()
        self.assertNotIn("test-auth-token", self.connection.credentials)
        self.assertEqual(
            self.connection.get_credentials()["auth_token"], "test-auth-token"
        )

    def test_twilio_token_and_signature(self) -> None:
        """Use case: Authorize a browser and authenticate callbacks. Expected result: scoped grants and rejected tampering."""
        import jwt
        from twilio.request_validator import RequestValidator
        from bloomerp.communication.builtins.voip.controller import adapter_for

        # 1. Generate a short-lived browser grant for this configured account.
        self.prepare_voip()
        adapter = adapter_for(self.connection)
        token = adapter.browser_token("staff-identity")
        claims = jwt.decode(
            token,
            "test-api-secret",
            algorithms=["HS256"],
            options={"verify_aud": False},
        )
        self.assertEqual(claims["sub"], self.connection.external_account_id)
        self.assertEqual(claims["grants"]["identity"], "staff-identity")
        self.assertEqual(claims["exp"] - claims["nbf"], 600)
        # 2. Verify exact callback URL and reject any tampered address or foreign account.
        url = "https://example.test/callback/"
        params = {
            "AccountSid": self.connection.external_account_id,
            "To": self.number.number,
        }
        signature = RequestValidator("test-auth-token").compute_signature(url, params)
        self.assertTrue(adapter.verify_webhook(url, params, signature))
        self.assertFalse(adapter.verify_webhook(url + "altered", params, signature))
        self.assertFalse(
            adapter.verify_webhook(
                url,
                {**params, "AccountSid": self.other_connection.external_account_id},
                signature,
            )
        )

