    def test_sms_dispatch_is_deduplicated(self) -> None:
        """Use case: Repeat a client send. Expected result: one persisted message and one carrier submission."""
        from unittest.mock import patch
        from bloomerp.communication.builtins.voip.controller import VoIPController

        self.prepare_voip()
        with (
            patch(
                "bloomerp.communication.builtins.voip.controller.adapter_for"
            ) as factory,
            patch(
                "bloomerp.communication.builtins.instant_messaging.controller.IMController.notify_message"
            ),
        ):
            factory.return_value.send_sms.return_value = "SM" + "7" * 32
            controller = VoIPController(self.normal_user)
            first = controller.send_message(self.chat.pk, "Hello", "one-send")
            repeated = controller.send_message(self.chat.pk, "Hello", "one-send")
            self.assertEqual(first.pk, repeated.pk)
            factory.return_value.send_sms.assert_called_once()
        self.assertEqual(self.chat.messages.count(), 1)

    def test_ambiguous_sms_is_not_resent(self) -> None:
        """Use case: Carrier request times out. Expected result: retrying the request cannot double-send the SMS."""
        from unittest.mock import patch
        from bloomerp.communication.builtins.voip.controller import VoIPController

        self.prepare_voip()
        with patch(
            "bloomerp.communication.builtins.voip.controller.adapter_for"
        ) as factory:
            factory.return_value.send_sms.side_effect = TimeoutError()
            controller = VoIPController(self.normal_user)
            with self.assertRaises(ValidationError):
                controller.send_message(self.chat.pk, "Hello", "uncertain-send")
            message = controller.send_message(self.chat.pk, "Hello", "uncertain-send")
            self.assertEqual(message.status, "pending")
            factory.return_value.send_sms.assert_called_once()

